CREATE DATABASE IF NOT EXISTS sigesporte CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sigesporte;
CREATE TABLE usuarios (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(180) NOT NULL,cpf CHAR(11) NULL UNIQUE,email VARCHAR(190) NULL UNIQUE,senha_hash VARCHAR(255) NOT NULL,ativo TINYINT(1) NOT NULL DEFAULT 1,deve_alterar_senha TINYINT(1) NOT NULL DEFAULT 1,ultimo_login_em DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE perfis (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(100) NOT NULL,slug VARCHAR(100) NOT NULL UNIQUE,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE permissoes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,chave VARCHAR(100) NOT NULL UNIQUE,descricao VARCHAR(190) NOT NULL) ENGINE=InnoDB;
CREATE TABLE usuarios_perfis (usuario_id BIGINT UNSIGNED NOT NULL,perfil_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(usuario_id,perfil_id),FOREIGN KEY(usuario_id) REFERENCES usuarios(id),FOREIGN KEY(perfil_id) REFERENCES perfis(id)) ENGINE=InnoDB;
CREATE TABLE perfis_permissoes (perfil_id BIGINT UNSIGNED NOT NULL,permissao_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(perfil_id,permissao_id),FOREIGN KEY(perfil_id) REFERENCES perfis(id),FOREIGN KEY(permissao_id) REFERENCES permissoes(id)) ENGINE=InnoDB;
CREATE TABLE tentativas_login (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,identificador_hash CHAR(64) NOT NULL,ip VARCHAR(45) NOT NULL,sucesso TINYINT(1) NOT NULL,motivo VARCHAR(100) NULL,ocorrido_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(identificador_hash,ocorrido_em),INDEX(ip,ocorrido_em)) ENGINE=InnoDB;
CREATE TABLE tokens_senha (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,expira_em DATETIME NOT NULL,usado_em DATETIME NULL,solicitado_ip VARCHAR(45) NOT NULL,FOREIGN KEY(usuario_id) REFERENCES usuarios(id)) ENGINE=InnoDB;
CREATE TABLE modalidades (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) NOT NULL UNIQUE,descricao TEXT NULL,tipo VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'ativo',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE categorias (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,modalidade_id BIGINT UNSIGNED NOT NULL,nome VARCHAR(100) NOT NULL,idade_min TINYINT UNSIGNED NOT NULL,idade_max TINYINT UNSIGNED NOT NULL,sexo VARCHAR(20) NOT NULL DEFAULT 'misto',status VARCHAR(20) NOT NULL DEFAULT 'ativo',UNIQUE(modalidade_id,nome),FOREIGN KEY(modalidade_id) REFERENCES modalidades(id)) ENGINE=InnoDB;
CREATE TABLE atletas (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(20) NOT NULL UNIQUE,nome VARCHAR(180) NOT NULL,nome_social VARCHAR(180) NULL,cpf CHAR(11) NOT NULL UNIQUE,nascimento DATE NOT NULL,sexo VARCHAR(20) NOT NULL,telefone VARCHAR(20) NULL,email VARCHAR(190) NULL,status VARCHAR(20) NOT NULL DEFAULT 'rascunho',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,INDEX(status,created_at),INDEX(nascimento)) ENGINE=InnoDB;
CREATE TABLE atletas_enderecos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,atleta_id BIGINT UNSIGNED NOT NULL UNIQUE,cep CHAR(8) NULL,municipio VARCHAR(120) NULL,bairro VARCHAR(120) NULL,logradouro VARCHAR(180) NULL,numero VARCHAR(20) NULL,FOREIGN KEY(atleta_id) REFERENCES atletas(id)) ENGINE=InnoDB;
CREATE TABLE responsaveis (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(180) NOT NULL,cpf CHAR(11) NULL,telefone VARCHAR(20) NULL,email VARCHAR(190) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE atletas_responsaveis (atleta_id BIGINT UNSIGNED NOT NULL,responsavel_id BIGINT UNSIGNED NOT NULL,parentesco VARCHAR(80) NOT NULL,principal TINYINT(1) NOT NULL DEFAULT 0,PRIMARY KEY(atleta_id,responsavel_id),FOREIGN KEY(atleta_id) REFERENCES atletas(id),FOREIGN KEY(responsavel_id) REFERENCES responsaveis(id)) ENGINE=InnoDB;
CREATE TABLE atletas_perfis_esportivos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,atleta_id BIGINT UNSIGNED NOT NULL,modalidade_principal_id BIGINT UNSIGNED NULL,categoria_id BIGINT UNSIGNED NULL,equipe_id BIGINT UNSIGNED NULL,iniciado_em DATE NULL,encerrado_em DATE NULL,FOREIGN KEY(atleta_id) REFERENCES atletas(id),FOREIGN KEY(modalidade_principal_id) REFERENCES modalidades(id)) ENGINE=InnoDB;
CREATE TABLE atletas_modalidades (atleta_id BIGINT UNSIGNED NOT NULL,modalidade_id BIGINT UNSIGNED NOT NULL,ativo TINYINT(1) NOT NULL DEFAULT 1,PRIMARY KEY(atleta_id,modalidade_id),FOREIGN KEY(atleta_id) REFERENCES atletas(id),FOREIGN KEY(modalidade_id) REFERENCES modalidades(id)) ENGINE=InnoDB;
CREATE TABLE tipos_documentos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,codigo VARCHAR(80) NOT NULL UNIQUE,nome VARCHAR(120) NOT NULL,exige_validade TINYINT(1) NOT NULL DEFAULT 0,ativo TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE atletas_documentos (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,atleta_id BIGINT UNSIGNED NOT NULL,tipo_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pendente',arquivo_storage_key VARCHAR(255) NULL,arquivo_nome_original VARCHAR(255) NULL,mime VARCHAR(100) NULL,bytes INT UNSIGNED NULL,validade DATE NULL,enviado_por BIGINT UNSIGNED NULL,enviado_em DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,FOREIGN KEY(atleta_id) REFERENCES atletas(id),FOREIGN KEY(tipo_id) REFERENCES tipos_documentos(id),FOREIGN KEY(enviado_por) REFERENCES usuarios(id),INDEX(atleta_id,status),INDEX(validade,status)) ENGINE=InnoDB;
CREATE TABLE logs_auditoria (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,usuario_id BIGINT UNSIGNED NULL,acao VARCHAR(100) NOT NULL,modulo VARCHAR(100) NOT NULL,entidade VARCHAR(100) NULL,entidade_id VARCHAR(50) NULL,dados_antes JSON NULL,dados_depois JSON NULL,ip VARCHAR(45) NULL,user_agent VARCHAR(255) NULL,ocorrido_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(usuario_id) REFERENCES usuarios(id),INDEX(modulo,entidade,entidade_id),INDEX(usuario_id,ocorrido_em)) ENGINE=InnoDB;
